function factorial(n){
  n = BigInt(n);
  if(n < 0n) return null;
  var r = 1n; for(var i = 2n; i <= n; i++) r *= i;
  return r;
}
function doubleFactorial(n){
  n = BigInt(n); if(n < 0n) return null;
  var r = 1n; for(var i = n; i > 0n; i -= 2n) r *= i;
  return r;
}
var EXPORTS = { factorial:factorial, doubleFactorial:doubleFactorial };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FactorialForgePure = EXPORTS; }
